import json

def norm(path):
    if path == "":
        return "/"
    parts = []
    abs_path = path.startswith("/")
    for p in path.split("/"):
        if p == "" or p == ".":
            continue
        if p == "..":
            if parts:
                parts.pop()
            continue
        parts.append(p)
    return "/" + "/".join(parts) if abs_path else "/".join(parts)

def parent(path):
    p = norm(path)
    if p == "/":
        return None
    i = p.rfind("/")
    return "/" if i == 0 else p[:i]

def depth_from_root(path):
    p = norm(path)
    if p == "/":
        return 0
    return len([x for x in p.split("/") if x])  # /testbed => 1

def ensure_dir(tree, path):
    p = norm(path)
    if p not in tree:
        tree[p] = "dir"

def ensure_file(tree, path):
    p = norm(path)
    tree[p] = "file"

def remove_path(tree, path):
    p = norm(path)
    for k in list(tree.keys()):
        if k == p or k.startswith(p + "/"):
            del tree[k]

