    cmd = w.get("command") or w.get("args", {}).get("command") or ""
    c = cmd.strip()

    # mkdir -p paths...
    if c.startswith("mkdir "):
        toks = c.split()
        paths = [t for t in toks[1:] if not t.startswith("-")]
        for p in paths:
            p = norm(p)
            cur = ""
            for part in [x for x in p.split("/") if x]:
                cur += "/" + part
                ensure_dir(tree, cur)
        continue

    # touch paths...
    if c.startswith("touch "):
        toks = c.split()
        for p in toks[1:]:
            p = norm(p)
            par = parent(p)
            if par and par in tree and tree.get(par) == "dir":
                ensure_file(tree, p)
        continue

    # rm / rm -r / rm -rf
    if c.startswith("rm "):
        toks = c.split()
        paths = [t for t in toks[1:] if not t.startswith("-")]
        for p in paths:
            remove_path(tree, p)
        continue

    # mv src dst
    if c.startswith("mv "):
        toks = c.split()
        if len(toks) >= 3:
            src = norm(toks[1]); dst = norm(toks[2])
            if src in tree:
                typ = tree[src]
                # move subtree
                moved = {}
                for k, v in list(tree.items()):
                    if k == src or k.startswith(src + "/"):
                        suffix = k[len(src):]
                        moved[dst + suffix] = v
                        del tree[k]
                par = parent(dst)
                if par and tree.get(par) == "dir":
                    tree.update(moved)
        continue

    # cp src dst (file only conservatively)
    if c.startswith("cp "):
        toks = c.split()
        if len(toks) >= 3:
            src = norm(toks[1]); dst = norm(toks[2])
            if tree.get(src) == "file":
