                if parent == "/" or parent in dirs:
                    files[p] = files.get(p, "")
        elif cmd.startswith("rm "):
            parts = cmd.split()
            if len(parts) >= 2:
                p = parts[1]
                if p in files:
                    del files[p]
        elif cmd.startswith("echo ") and " > " in cmd:
            left, right = cmd.split(" > ", 1)
            p = right.strip()
            content = left[5:]
            if (content.startswith("'") and content.endswith("'")) or (content.startswith('"') and content.endswith('"')):
