            parent = "/" + "/".join([x for x in p.strip("/").split("/")[:-1] if x]) if "/" in p.strip("/") else "/"
            dirs = files.setdefault("__dirs__", set())
            if parent == "/" or parent in dirs:
                files[p] = content + "\n"
    elif app == "calendar" and action == "create_event":
        cal = w.get("calendar_path")
        if cal:
            dirs = files.setdefault("__dirs__", set())
            parent = "/" + "/".join([x for x in cal.strip("/").split("/")[:-1] if x]) if "/" in cal.strip("/") else "/"
            comps = parent.strip("/").split("/") if parent != "/" else []
            cur = ""
            for c in comps:
                cur += "/" + c
                dirs.add(cur)
            files.setdefault(cal, "")
    elif app == "excel" and action == "create_new_file":
        p = w.get("path")
        parent = "/" + "/".join([x for x in p.strip("/").split("/")[:-1] if x]) if "/" in p.strip("/") else "/"
