import json

def shell_quote(name):
    if name == "":
        return "''"
    safe = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._/-")
    if all(c in safe for c in name):
        return name
    return "'" + name.replace("'", "'\"'\"'") + "'"

