import json

def norm(path):
    if path == "":
        return "/"
    parts = []
    abs_path = path.startswith("/")
    for p in path.split("/"):
        if p == "" or p == ".":
            continue
        if p == "..":
            if parts:
                parts.pop()
            continue
        parts.append(p)
    return ("/" if abs_path else "") + "/".join(parts) if parts or abs_path else "."

def parent(path):
    p = norm(path)
    if p == "/":
        return None
    if "/" not in p.rstrip("/"):
        return "."
    q = p.rstrip("/")
    i = q.rfind("/")
    if i == 0:
        return "/"
    return q[:i]

def basename(path):
    p = norm(path).rstrip("/")
    if p == "/":
        return "/"
    return p.split("/")[-1]

def parse_trace(trace_text):
