        path = line.rstrip("\n")
        entries[norm(path)] = True
    return entries

def parse_list_inventory(text):
    # Keep as fallback only; trace is primary.
    entries = {}
    if not text:
        return entries
    try:
        obj = json.loads(text)
        def walk(node, cur):
            if isinstance(node, dict):
                for k, v in node.items():
                    p = norm(cur.rstrip("/") + "/" + k if cur != "/" else "/" + k)
                    entries[p] = True
                    walk(v, p)
            elif isinstance(node, list):
                for item in node:
                    if isinstance(item, str):
                        p = norm(cur.rstrip("/") + "/" + item if cur != "/" else "/" + item)
                        entries[p] = True
                    else:
                        walk(item, cur)
        walk(obj, "/testbed/data")
    except Exception:
        pass
    return entries

